### Code Snippets

```
try {
Block of code to try
} catch(
err
) {
Block of code to handle errors
}

---

let x = 5;
try {
x = y + 1;
} catch(err) {
let text = err.name;
}

---

try {
let x = y;
let y = 5;
} catch(err) {
let text = err.name;
}

---

let anna = 5;
try {
anna(5);
} catch(err) {
let text = err.name;
}

---

let num = 1;
try {
num.toUpperCase();
} catch(err) {
let text = err.name;
}

---

try {
new Array(-1);
} catch(err) {
let text = err.name;
}

---

let num = 1;
try {
num.toPrecision(500);   // A number cannot have 500 
 significant digits
} catch(err) {
let text = err.name;
}

---

try {
decodeURI("%%%");   // You cannot URI decode 
  percent signs
} catch(err) {
document.getElementById("demo").innerHTML = err.name;
}

---

// This line cannot be parsed by JavaScript
let fName = "John);
// Execution stops here

---

try {
let x = Math.round(4.6;)
} catch(err) {
let text = err.name + " " + err.description;
}

